import numpy as np
from scipy.optimize import minimize

class HybridGA:
    def __init__(self, budget=10000, dim=10, population_size=20, mutation_rate=0.1, crossover_rate=0.8, local_search_steps=5):
        self.budget = budget
        self.dim = dim
        self.population_size = population_size
        self.mutation_rate = mutation_rate
        self.crossover_rate = crossover_rate
        self.local_search_steps = local_search_steps
        self.bounds = np.array([(-5.0, 5.0)] * dim) # Added bounds here
        self.evaluations = 0

    def initialize_population(self):
        return np.random.uniform(self.bounds[:, 0], self.bounds[:, 1], size=(self.population_size, self.dim))

    def evaluate(self, func, individual):
        if self.evaluations < self.budget:
            self.evaluations += 1
            return func(individual)
        else:
            return np.inf  # or some other large value to discourage this solution


    def select_parents(self, population, fitnesses):
        # Tournament selection
        tournament_size = 2
        parents = []
        for _ in range(2): # Select two parents
            winner_index = np.random.randint(0, self.population_size)
            for _ in range(tournament_size - 1):
                contestant_index = np.random.randint(0, self.population_size)
                if fitnesses[contestant_index] < fitnesses[winner_index]:
                    winner_index = contestant_index
            parents.append(population[winner_index])
        return parents

    def crossover(self, parents):
        if np.random.rand() < self.crossover_rate:
            crossover_point = np.random.randint(1, self.dim)
            child = np.concatenate((parents[0][:crossover_point], parents[1][crossover_point:]))
            return child
        else:
            return parents[np.random.randint(0, 2)]

    def mutate(self, individual):
        mutated_individual = np.copy(individual)
        for i in range(self.dim):
            if np.random.rand() < self.mutation_rate:
                mutated_individual[i] += np.random.normal(0, 0.5) # Gaussian mutation
                mutated_individual[i] = np.clip(mutated_individual[i], self.bounds[i, 0], self.bounds[i, 1])  # Keep within bounds
        return mutated_individual

    def local_search(self, func, individual):
        try:
            result = minimize(lambda x: self.evaluate(func, x), individual, method='L-BFGS-B', bounds=self.bounds, jac=False, options={'maxiter': self.local_search_steps}) # Added bounds to minimize
            if result.success:
                return result.x, result.fun
            else:
                return individual, self.evaluate(func, individual) # If local search fails, return the original individual and its value
        except Exception as e:
            print(f"Local search failed: {e}") # Handle potential errors in local search
            return individual, self.evaluate(func, individual)


    def __call__(self, func):
        population = self.initialize_population()
        fitnesses = np.array([self.evaluate(func, individual) for individual in population])
        self.evaluations = self.population_size # Account for initial population evaluations
        self.f_opt = np.min(fitnesses)
        self.x_opt = population[np.argmin(fitnesses)]

        while self.evaluations < self.budget:
            # Genetic Algorithm step
            parents = self.select_parents(population, fitnesses)
            child = self.crossover(parents)
            child = self.mutate(child)

            # Local Search Step
            child, child_fitness = self.local_search(func, child)


            if child_fitness < self.f_opt:
                self.f_opt = child_fitness
                self.x_opt = child

            # Replace the worst individual in the population with the child
            worst_index = np.argmax(fitnesses)
            population[worst_index] = child
            fitnesses[worst_index] = child_fitness


            fitnesses = np.array([self.evaluate(func, individual) for individual in population]) # Re-evaluate fitnesses

        return self.f_opt, self.x_opt

import numpy as np
