class GradientEnhancedES:
    def __init__(self, budget=10000, dim=10, population_size=5, offspring_size=20, mutation_strength_init=1.0,  local_search_steps=10):
        self.budget = budget
        self.dim = dim
        self.population_size = population_size  # mu
        self.offspring_size = offspring_size  # lambda
        self.mutation_strength_init = mutation_strength_init
        self.mutation_strength = np.full(population_size, mutation_strength_init)
        self.local_search_steps = local_search_steps
        self.bounds = np.array([(-5.0, 5.0)] * dim)
        self.evaluations = 0

    def initialize_population(self):
        return np.random.uniform(self.bounds[:, 0], self.bounds[:, 1], size=(self.population_size, self.dim))

    def evaluate(self, func, individual):
        if self.evaluations < self.budget:
            self.evaluations += 1
            return func(individual)
        else:
            return np.inf

    def mutate(self, individual, mutation_strength):
        mutated_individual = individual + np.random.normal(0, mutation_strength, size=self.dim)
        return np.clip(mutated_individual, self.bounds[:, 0], self.bounds[:, 1])

    def local_search(self, func, individual):
        try:
            result = minimize(lambda x: self.evaluate(func, x), individual, method='L-BFGS-B', bounds=self.bounds, jac=False, options={'maxiter': self.local_search_steps})
            if result.success:
                return result.x, result.fun
            else:
                return individual, self.evaluate(func, individual)
        except Exception as e:
            #print(f"Local search failed: {e}") # Removed print for efficiency
            return individual, self.evaluate(func, individual)

    def __call__(self, func):
        population = self.initialize_population()
        fitnesses = np.array([self.evaluate(func, individual) for individual in population])
        self.evaluations += self.population_size  # Account for initial population evaluations
        best_index = np.argmin(fitnesses)
        self.x_opt = population[best_index]
        self.f_opt = fitnesses[best_index]

        while self.evaluations < self.budget:
            offspring = np.zeros((self.offspring_size, self.dim))
            offspring_fitnesses = np.zeros(self.offspring_size)
            mutation_strengths = np.zeros(self.offspring_size)

            for i in range(self.offspring_size):
                parent_index = np.random.randint(0, self.population_size)
                mutation_strength = self.mutation_strength[parent_index] * np.exp(np.random.normal(0, 0.2)) # Adjust mutation strength
                mutation_strength = np.clip(mutation_strength, 1e-6, 5) # Clip mutation strength to reasonable values
                mutated_individual = self.mutate(population[parent_index], mutation_strength)
                offspring[i] = mutated_individual
                offspring_fitnesses[i] = self.evaluate(func, mutated_individual)
                mutation_strengths[i] = mutation_strength

            #Selection
            combined_population = np.vstack((population, offspring))
            combined_fitnesses = np.concatenate((fitnesses, offspring_fitnesses))
            indices = np.argsort(combined_fitnesses)
            selected_indices = indices[:self.population_size]
            population = combined_population[selected_indices]
            fitnesses = combined_fitnesses[selected_indices]
            self.mutation_strength = np.array([mutation_strengths[i % self.offspring_size] if i >= self.population_size else self.mutation_strength[i] for i in selected_indices])
            best_index = np.argmin(fitnesses)
            if fitnesses[best_index] < self.f_opt:
                self.f_opt = fitnesses[best_index]
                self.x_opt = population[best_index]


            # Local Search Refinement (on the best individual, only occasionally)
            if self.evaluations % (self.population_size * self.offspring_size) == 0:  # Apply local search less frequently.  Adjust this factor as needed.
                self.x_opt, self.f_opt = self.local_search(func, self.x_opt)
        return self.f_opt, self.x_opt

