class HybridGA_AdaptiveMutation:
    def __init__(self, budget=10000, dim=10, population_size=20, mutation_rate=0.1, crossover_rate=0.8, local_search_steps=5, mutation_rate_adapt_factor=0.95):
        self.budget = budget
        self.dim = dim
        self.population_size = population_size
        self.mutation_rate = mutation_rate
        self.crossover_rate = crossover_rate
        self.local_search_steps = local_search_steps
        self.bounds = np.array([(-5.0, 5.0)] * dim)
